INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Stehen hier Prozesse über Menschen?', 2, '[{"text": "Nein", "correct": true, "because": "Individuen über Prozesse"}, {"text": "Ja", "correct": false, "because": "Menschen im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Wert priorisiert die Teamarbeit?', 3, '[{"text": "Individuen und Interaktionen", "correct": true, "because": "Zusammenarbeit zählt"}, {"text": "Umfassende Dokumentation", "correct": false, "because": "Weniger wichtig"}, {"text": "Vertragsverhandlungen", "correct": false, "because": "Kundenorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien fördern Flexibilität?', 5, '[{"text": "Funktionierende Software", "correct": true, "because": "Lieferung über Pläne"}, {"text": "Reaktion auf Veränderung", "correct": true, "because": "Anpassung bevorzugt"}, {"text": "Feste Prozesse", "correct": false, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kundenorientierung ist zentral. b) Dokumentation ist wichtiger als Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software über Dokumentation"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Werten?', 4, '[{"text": "Kundenzusammenarbeit", "correct": false, "because": "Kernprinzip"}, {"text": "Funktionierende Software", "correct": false, "because": "Hauptfokus"}, {"text": "Strikte Pläne", "correct": true, "because": "Veränderung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verträge hier wichtiger sind als Zusammenarbeit?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenzusammenarbeit zählt"}, {"text": "Ja", "correct": false, "because": "Verträge sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grundsatz hilft bei schnellen Änderungen?', 3, '[{"text": "Reaktion auf Veränderung", "correct": true, "because": "Flexibilität fördern"}, {"text": "Umfassende Dokumentation", "correct": false, "because": "Weniger Priorität"}, {"text": "Individuen", "correct": false, "because": "Teamfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte unterstützen den Erfolg?', 5, '[{"text": "Individuen und Interaktionen", "correct": true, "because": "Teamarbeit stärken"}, {"text": "Funktionierende Software", "correct": true, "because": "Lieferung im Fokus"}, {"text": "Lange Planung", "correct": false, "because": "Anpassung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Software ist wichtiger als Dokumentation. b) Veränderung wird ignoriert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Veränderung willkommen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Kundenzusammenarbeit", "correct": false, "because": "Kernprinzip"}, {"text": "Reaktion auf Veränderung", "correct": false, "because": "Flexibilität zentral"}, {"text": "Feste Verträge", "correct": true, "because": "Zusammenarbeit bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Dokumentation hier das Wichtigste?', 2, '[{"text": "Nein", "correct": true, "because": "Software hat Vorrang"}, {"text": "Ja", "correct": false, "because": "Dokumentation sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien fördern schnelle Lieferung?', 4, '[{"text": "Funktionierende Software", "correct": true, "because": "Ergebnisse zählen"}, {"text": "Kundenzusammenarbeit", "correct": true, "because": "Bedürfnisse klären"}, {"text": "Strikte Prozesse", "correct": false, "because": "Flexibilität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier niemand mit Kunden spricht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenzusammenarbeit zentral"}, {"text": "Ja", "correct": false, "because": "Kunden im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem neuen Projekt?', 3, '[{"text": "Individuen und Interaktionen", "correct": true, "because": "Teamarbeit stärken"}, {"text": "Umfassende Dokumentation", "correct": false, "because": "Software wichtiger"}, {"text": "Vertragsdetails", "correct": false, "because": "Zusammenarbeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Veränderung ist willkommen. b) Prozesse sind wichtiger als Menschen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Menschen über Prozesse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen diese Werte?', 5, '[{"text": "Schnelle Anpassung", "correct": true, "because": "Reaktion auf Veränderung"}, {"text": "Teamfokus", "correct": true, "because": "Individuen im Vordergrund"}, {"text": "Lange Dokumentation", "correct": false, "because": "Software zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Funktionierende Software", "correct": false, "because": "Hauptziel"}, {"text": "Kundenzusammenarbeit", "correct": false, "because": "Kernprinzip"}, {"text": "Feste Pläne", "correct": true, "because": "Veränderung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Menschen hier zweitrangig?', 3, '[{"text": "Nein", "correct": true, "because": "Individuen über Prozesse"}, {"text": "Ja", "correct": false, "because": "Team im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Software hier unwichtig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionierende Software zentral"}, {"text": "Ja", "correct": false, "because": "Ergebnisse im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Wert wähle ich für besseren Kundenkontakt?', 4, '[{"text": "Kundenzusammenarbeit", "correct": true, "because": "Kundenbedürfnisse klären"}, {"text": "Feste Verträge", "correct": false, "because": "Zusammenarbeit zählt"}, {"text": "Lange Dokumentation", "correct": false, "because": "Software wichtiger"}]');
